#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(dplyr);library(tidyr);library(readr);library(ggplot2);library(ggthemes)})
a<-commandArgs(trailingOnly=TRUE);stopifnot(length(a)==1)
w<-read_csv(file.path(a[1],'weights_with_se.csv'),show_col_types=FALSE)
o<-read_csv(file.path(a[1],'observation_residuals.csv'),show_col_types=FALSE)
stopifnot(max(w$year)==2028,max(o$year[o$dataset=='fishery'])==2025,max(o$year[o$dataset=='BTS'])==2026)
d<-bind_rows(o |> transmute(year,age=age_bin,weight_kg=observed_kg,source=if_else(dataset=='fishery','Fishery observations','BTS observations')),w |> filter(dataset=='fishery') |> transmute(year,age=age_bin,weight_kg,source='Model fishery weights')) |> filter(between(age,3,10),is.finite(weight_kg),weight_kg>0) |> group_by(source,age) |> mutate(reference_kg=mean(weight_kg[year<=2026]),anomaly=weight_kg/reference_kg-1) |> ungroup() |> mutate(source=factor(source,levels=c('Fishery observations','BTS observations','Model fishery weights')))
write_csv(d,'2026/tables/waa-heatmap-bts-double-cv-through-2028.csv')
ref <- read_csv('2026/tables/waa-heatmap-through-2028.csv',show_col_types=FALSE) |> distinct(source,age,reference_kg)
d <- d |> select(-reference_kg,-anomaly) |> left_join(ref,by=c('source','age')) |> mutate(anomaly=weight_kg/reference_kg-1,source=factor(source,levels=c('Fishery observations','BTS observations','Model fishery weights')))
stopifnot(!anyNA(d$reference_kg))
write_csv(d,'2026/tables/waa-heatmap-bts-double-cv-through-2028.csv')
p<-ggplot(d,aes(age,year,fill=anomaly))+geom_tile()+geom_text(aes(label=formatC(weight_kg,format='f',digits=2)),size=2.5)+facet_grid(.~source)+scale_y_reverse(breaks=seq(1970,2030,5),limits=c(2028.7,1969.3))+scale_x_continuous(breaks=3:10,expand=expansion(add=.5))+scale_fill_gradient2(low='#756BB1',mid='white',high='#B33B32',midpoint=0,limits=c(-.5,.5),oob=scales::squish,name='Relative\nanomaly',breaks=c(-.5,0,.5),labels=c('≤ −0.5','0','≥ 0.5'))+geom_hline(yintercept=2026.5,linetype=2,linewidth=.4)+labs(x='Age',y='Year',title='Weight at age: BTS 2025-2026 observation CVs doubled',subtitle='Cell labels: kg per fish. Dashed line separates 2027–2028 predictions from years through 2026.',caption='Saved WtAgeRE joint fit: bts_2025_2026_double_cv_20261108 / attempt-001.\nFishery observations end in 2025; BTS observations end in 2026. Model fishery weights include estimates without observations.\nAnomalies are relative to the baseline panel-specific age means through 2026; colors saturate at ±50%. Ages 3–10 shown.')+theme_few(base_size=11)+theme(panel.grid.major=element_line(color='grey92',linewidth=.3),strip.background=element_blank(),plot.caption=element_text(hjust=0,size=8),legend.position='right')
ggsave('2026/assets/waa-heatmap-bts-double-cv-through-2028.png',p,width=12,height=15,dpi=180)
ggsave('2026/tables/waa-heatmap-bts-double-cv-through-2028.pdf',p,width=12,height=15,device=cairo_pdf)
